from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal('0.01')


def _quantize(value):
    result = value.quantize(CENTS, rounding=ROUND_HALF_UP)
    if result == 0:
        result = abs(result)  # avoid "-0.00"
    return result


def _fmt(value):
    return f'{_quantize(value):.2f}'


def invoice(lines, tax_rate):
    rate = Decimal(tax_rate)
    subtotal = Decimal('0')
    tax = Decimal('0')
    for row in lines:
        line_total = _quantize(Decimal(row['unit_price']) * row['qty'])
        subtotal += line_total
        if row['taxable']:
            tax += _quantize(line_total * rate)
    total = subtotal + tax
    return {'subtotal': _fmt(subtotal), 'tax': _fmt(tax), 'total': _fmt(total)}
